def det(A):
    if not A:
        return 1                                   # det of the 0x0 matrix is the empty product
    total = 0
    for j, a in enumerate(A[0]):
        if a == 0:
            continue                               # zero entries contribute nothing; skip their subtree
        minor = [row[:j] + row[j + 1:] for row in A[1:]]
        total += (-1) ** j * a * det(minor)
    return total
